        m.insert("price".to_string(), self.parent.parse_x18(self.safe_string_k(trade.clone(), "price", &[])));
        m.insert("amount".to_string(), self.parent.parse_x18(self.safe_string_k(trade.clone(), "filled_qty", &[])));
